def backfill_actor_username(apps, schema_editor):
    """为存量审计行补写操作人用户名快照。"""
    AdminAuditLog = apps.get_model("admin_api", "AdminAuditLog")
    User = apps.get_model("users", "User")
    usernames = dict(User.objects.values_list("id", "username"))
    updates = []
    for log in AdminAuditLog.objects.filter(actor_id__isnull=False).only(
        "id", "actor_id", "actor_username"
    ):
        if log.actor_username:
            continue
        username = usernames.get(log.actor_id)
        if not username:
            continue
        log.actor_username = username
        updates.append(log)
    if updates:
        AdminAuditLog.objects.bulk_update(updates, ["actor_username"], batch_size=500)


def clear_actor_username(apps, schema_editor):
    AdminAuditLog = apps.get_model("admin_api", "AdminAuditLog")
    AdminAuditLog.objects.update(actor_username="")


